type AcceptanceOfDelivery struct {
	AcceptanceOfDeliveryID string `json:"acceptanceofDeliveryId"`
	ExpectedDeliveryDate   string `json:"ExpectedDeliveryDate"`
	ActualDeliveryDate     string `json:"actualDeliveryDate"`
	TerminationDays        int    `json:"terminationDays"`
	Status                string `json:"status"`
	DiffDays              int    `json:"diffDays"`
	Type                  string `json:"type"`
	DateTime              string `json:"dateTime"`
}

func (s *SmartContract) AcceptanceOfDelivery(ctx contractapi.TransactionContextInterface, reqOrderId string,
	acceptanceofDeliveryId string, actualDeliveryDate string) (map[string]interface{}, error) {

	// --- Get order directly using GetState ---
	orderAsBytes, err := ctx.GetStub().GetState(reqOrderId)
	if err != nil {
		return nil, fmt.Errorf("failed to get order: %v", err)
	}
	if len(orderAsBytes) == 0 {
		return nil, fmt.Errorf("%s does not exist", reqOrderId)
	}

	order := make(map[string]interface{})
	_ = json.Unmarshal(orderAsBytes, &order)

	agreedDeliveryDate1 := order["agreedDeliveryDate"].(string)
	terminationDays1 := order["terminationDays"].(float64)

	var contractTerminated bool
	var status string

	date1, err := time.Parse("2006-01-02", actualDeliveryDate)
	date2, err := time.Parse("2006-01-02", agreedDeliveryDate1)
	if err != nil {
		return nil, fmt.Errorf("error parsing dates: %v", err)
	}

	if date2.After(date1) {
		return nil, fmt.Errorf("Cannot exercise late delivery before delivery date")
	}

	diff := date1.Sub(date2)
	diffDays := float64(diff.Hours() / 24)

	if diffDays > terminationDays1 {
		contractTerminated = true
		status = "OUTSIDE_INSPECTION_PERIOD"
	} else {
		contractTerminated = false
		status = "PASSED_TESTING"
	}

	// --- Update and persist the order back using PutState ---
	order["contractTerminated"] = contractTerminated
	order["delayedDays"] = diffDays
	order["actualDeliveryDate"] = actualDeliveryDate

	orderUpdatedBytes, _ := json.Marshal(order)
	err = ctx.GetStub().PutState(reqOrderId, orderUpdatedBytes)
	if err != nil {
		return nil, fmt.Errorf("failed to update order state: %v", err)
	}

	// --- Build acceptance of delivery record ---
	details := map[string]interface{}{
		"acceptanceofDeliveryId": acceptanceofDeliveryId,
		"TerminationDays":        terminationDays1,
		"AgreedDeliveryDate":     agreedDeliveryDate1,
		"ActualDeliveryDate":     actualDeliveryDate,
		"ContractTerminated":     contractTerminated,
		"DiffDays":               diffDays,
		"Status":                 status,
		"Type":                   "acceptanceofdelivery",
		"DateTime":               time.Now().Format("2006-Jan-02 3:4:5 PM Mon"),
	}

	detailsBytes, err := json.Marshal(details)
	if err != nil {
		return nil, fmt.Errorf("error marshaling delivery details: %v", err)
	}

	// --- Save the delivery acceptance directly using PutState ---
	err = ctx.GetStub().PutState(acceptanceofDeliveryId, detailsBytes)
	if err != nil {
		return nil, fmt.Errorf("failed to save acceptance of delivery: %v", err)
	}

	return details, nil
}


