// FragileGoods function implementation
func (s *SmartContract) FragileGoods(ctx contractapi.TransactionContextInterface, requestOrderId string, FragileGoodsId string, accelerationMin int, accelerationMax int, accelerometerReadings string, accelerationBreachPenalty int) error {
	// Validate input
	if accelerationBreachPenalty < 0 {
		return errors.New("Provide a valid input for accelerationBreachPenalty")
	}

	if accelerationMin >= accelerationMax {
		return errors.New("accelerationMin should be less than accelerationMax")
	}

	// Retrieve order details from supplychaindata chaincode
	response := ctx.GetStub().InvokeChaincode("supplychaindata", [][]byte{[]byte("GetState"), []byte(requestOrderId)}, "mychannel")
	if response.Status != 200 {
		return errors.New("Order does not exist: " + requestOrderId)
	}

	// Parse order data
	var order map[string]interface{}
	err := json.Unmarshal(response.Payload, &order)
	if err != nil {
		return err
	}

	// Get cost of goods from order
	costOfGoods := order["totalAmountPayable"].(float64)

	// Process accelerometer readings
	shocks := 0
	readings := strings.Split(accelerometerReadings, " ")
	for _, val := range readings {
		accel, err := strconv.Atoi(val)
		if err != nil {
			return errors.New("Invalid accelerometer reading: " + val)
		}
		if accel < accelerationMin || accel > accelerationMax {
			shocks++
		}
	}

	// Calculate penalty and payable amount
	totalPenalty := float64(shocks * accelerationBreachPenalty)
	payableAmount := costOfGoods - totalPenalty
	if payableAmount < 0 {
		payableAmount = 0
	}

	// Update order with penalty details
	order["fragilePenalty"] = totalPenalty
	order["amount_after_fragilePenalty"] = payableAmount
	order["totalAmountPayable"] = payableAmount

	orderJSON, err := json.Marshal(order)
	if err != nil {
		return err
	}

	// Store updated order in supplychaindata chaincode
	ccUpdateArgs := [][]byte{[]byte("PutState"), []byte(requestOrderId), orderJSON}
	updateResponse := ctx.GetStub().InvokeChaincode("supplychaindata", ccUpdateArgs, "mychannel")
	if updateResponse.Status != 200 {
		return errors.New("Failed to update order in supplychaindata chaincode")
	}

	// Create struct for storing in ledger
	details := FragileGoods{
		FragileGoodsId:            FragileGoodsId,
		AccelerationMin:           accelerationMin,
		AccelerationMax:           accelerationMax,
		AccelerometerReadings:     accelerometerReadings,
		AccelerationBreachPenalty: accelerationBreachPenalty,
		CostOfGoods:               costOfGoods,
		NumberOfShocks:            shocks,
		TotalPenalty:              totalPenalty,
		PayableAmount:             payableAmount,
		Type:                      "fragilegoods",
		DateTime:                  ctx.GetStub().GetTxTimestamp().String(),
	}

	// Convert to JSON
	detailsJSON, err := json.Marshal(details)
	if err != nil {
		return err
	}

	// Store fragile goods details in supplychaindata chaincode
	ccDetailsArgs := [][]byte{[]byte("PutState"), []byte(FragileGoodsId), detailsJSON}
	detailsResponse := ctx.GetStub().InvokeChaincode("supplychaindata", ccDetailsArgs, "mychannel")
	if detailsResponse.Status != 200 {
		return errors.New("Failed to store fragile goods details in supplychaindata chaincode")
	}

	fmt.Println("Fragile goods penalty details stored successfully:", details)
	return nil
}
