type MonthlyInstallment struct {
	Amount          float64 `json:"amount"`
	Rate            float64 `json:"rate"`
	Months          int     `json:"months"`
	MonthlyEMI      float64 `json:"monthly_installment"`
	TotalAmount     float64 `json:"total_amount"`
	TotalInterest   float64 `json:"total_interest"`
}

func (s *SmartContract) MonthlyInstallment(ctx contractapi.TransactionContextInterface, amount float64, rate float64, months int) (string, error) {
	// Validate input
	if amount <= 0 || months <= 0 {
		return "", errors.New("Provide a valid input for amount/months")
	}
	if rate < 0 {
		return "", errors.New("Provide a valid input for rate")
	}

	// Calculate interest per month
	interest := (amount * (rate * 0.01)) / float64(months)
	monthlyEMI := (amount / float64(months)) + interest
	totalAmount := float64(months) * monthlyEMI
	totalInterest := interest * float64(months)

	// Store result in struct
	result := MonthlyInstallment{
		Amount:        amount,
		Rate:          rate,
		Months:        months,
		MonthlyEMI:    math.Round(monthlyEMI*100) / 100, // Rounding to 2 decimal places
		TotalAmount:   math.Round(totalAmount*100) / 100,
		TotalInterest: math.Round(totalInterest*100) / 100,
	}

	// Convert to JSON
	resultJSON, err := json.Marshal(result)
	if err != nil {
		return "", err
	}

	// Invoke another chaincode (supplychaindata) and store data
	ccArgs := [][]byte{[]byte("PutState"), []byte(strconv.FormatFloat(amount, 'f', 2, 64)), resultJSON}
	response := ctx.GetStub().InvokeChaincode("supplychaindata", ccArgs, "mychannel")
	if response.Status != 200 {
		return "", errors.New("failed to store data in supplychaindata chaincode")
	}

	fmt.Println("Monthly Installment stored successfully in supplychaindata:", result)
	return string(resultJSON), nil
