// ClientRegistration registers a new client under a given policy
func (s *SmartContract) ClientRegistration(ctx contractapi.TransactionContextInterface, clientID, name, address, phoneNo, company, policyID string) (*ClientDetails, error) {

	// Generate composite key for the client
	clientKey, err := ctx.GetStub().CreateCompositeKey("client", []string{clientID, company, policyID})
	if err != nil {
		return nil, fmt.Errorf("failed to create composite key: %v", err)
	}

	// Check if client already exists
	clientBytes, err := ctx.GetStub().GetState(clientKey)
	if err != nil {
		return nil, fmt.Errorf("failed to read client state: %v", err)
	}
	if clientBytes != nil {
		return nil, fmt.Errorf("client ID %s is already present", clientID)
	}

	// Generate composite key for policy
	policyKey, err := ctx.GetStub().CreateCompositeKey(company, []string{policyID})
	if err != nil {
		return nil, fmt.Errorf("failed to create policy composite key: %v", err)
	}

	// Check if policy exists
	policyBytes, err := ctx.GetStub().GetState(policyKey)
	if err != nil {
		return nil, fmt.Errorf("failed to read policy state: %v", err)
	}
	if policyBytes == nil {
		return nil, fmt.Errorf("policy ID %s does not exist", policyID)
	}

	// Parse policy details
	var policyDetails map[string]interface{}
	err = json.Unmarshal(policyBytes, &policyDetails)
	if err != nil {
		return nil, fmt.Errorf("failed to parse policy details: %v", err)
	}

	// Set policy number (Hardcoded as "7875", update as needed)
	policyNumber := "7875"

	// Get current timestamp
	dateTime := time.Now().Format("2006-01-02 15:04:05")

	// Prepare client details
	clientDetails := ClientDetails{
		ClientID:        clientID,
		Name:            name,
		Address:         address,
		PhoneNo:         phoneNo,
		PolicyID:        policyID,
		InsuranceCompany: policyDetails["company"].(string),
		PolicyNumber:    policyNumber,
		PolicyName:      policyDetails["policy_Name"].(string),
		ClaimAmount:     policyDetails["claimAmount"].(string),
		Status:          "active",
		DateTime:        dateTime,
		Type:            "clientdetails",
	}

	// Convert struct to JSON
	clientDetailsBytes, err := json.Marshal(clientDetails)
	if err != nil {
		return nil, fmt.Errorf("failed to serialize client details: %v", err)
	}

	// Store client details in ledger
	err = ctx.GetStub().PutState(clientKey, clientDetailsBytes)
	if err != nil {
		return nil, fmt.Errorf("failed to store client details: %v", err)
	}

	return &clientDetails, nil
}
