func (s *SmartContract) ClientRegistration(ctx contractapi.TransactionContextInterface, clientID, name, address, phoneNo, company, policyID string) (*ClientDetails, error) {

	// Create client composite key manually
	clientKey := "client-" + clientID + "-" + company + "-" + policyID

	// --- Check if client already exists via InvokeChaincode ---
	getClientArgs := [][]byte{[]byte("GetData"), []byte(clientKey)}
	clientResp := ctx.GetStub().InvokeChaincode("genericdata", getClientArgs, "mychannel")
	if clientResp.Status != 200 {
		return nil, fmt.Errorf("failed to invoke GetData for client: %s", clientResp.Message)
	}
	if len(clientResp.Payload) > 0 {
		return nil, fmt.Errorf("client ID %s is already present", clientID)
	}

	// --- Check if policy exists via InvokeChaincode ---
	policyKey := company + "-" + policyID
	getPolicyArgs := [][]byte{[]byte("GetData"), []byte(policyKey)}
	policyResp := ctx.GetStub().InvokeChaincode("genericdata", getPolicyArgs, "mychannel")
	if policyResp.Status != 200 {
		return nil, fmt.Errorf("failed to invoke GetData for policy: %s", policyResp.Message)
	}
	if len(policyResp.Payload) == 0 {
		return nil, fmt.Errorf("policy ID %s does not exist", policyID)
	}

	var policyDetails map[string]interface{}
	err := json.Unmarshal(policyResp.Payload, &policyDetails)
	if err != nil {
		return nil, fmt.Errorf("failed to parse policy details: %v", err)
	}

	// Set policy number (Hardcoded as "7875", can be made dynamic)
	policyNumber := "7875"

	// Timestamp
	dateTime := time.Now().Format("2006-01-02 15:04:05")

	clientDetails := ClientDetails{
		ClientID:         clientID,
		Name:             name,
		Address:          address,
		PhoneNo:          phoneNo,
		PolicyID:         policyID,
		InsuranceCompany: policyDetails["company"].(string),
		PolicyNumber:     policyNumber,
		PolicyName:       policyDetails["policy_Name"].(string),
		ClaimAmount:      policyDetails["claimAmount"].(string),
		Status:           "active",
		DateTime:         dateTime,
		Type:             "clientdetails",
	}

	clientDetailsBytes, err := json.Marshal(clientDetails)
	if err != nil {
		return nil, fmt.Errorf("failed to serialize client details: %v", err)
	}

	// --- Store client details using InvokeChaincode ---
	putArgs := [][]byte{[]byte("PutData"), []byte(clientKey), clientDetailsBytes}
	putResp := ctx.GetStub().InvokeChaincode("genericdata", putArgs, "mychannel")
	if putResp.Status != 200 {
		return nil, fmt.Errorf("failed to invoke PutData for client: %s", putResp.Message)
	}

	return &clientDetails, nil
}

