func (s *SmartContract) PerishableGoods(ctx contractapi.TransactionContextInterface, PerishableGoodsId string, minTemperature, maxTemperature, minHumidity, maxHumidity, penaltyFactor int, tempSensorReading, humSensorReading string, costofGoods int, agreedDeliveryDate, actualDeliveryDate string, terminationDays int) error {
	if penaltyFactor < 0 {
		return errors.New("Provide a valid input for penaltyFactor")
	}

	parsedAgreedDate, err := time.Parse("2006-01-02", agreedDeliveryDate)
	if err != nil {
		return errors.New("Provide correct date format yyyy-mm-dd for agreedDeliveryDate")
	}

	parsedActualDate, err := time.Parse("2006-01-02", actualDeliveryDate)
	if err != nil {
		return errors.New("Provide correct date format yyyy-mm-dd for actualDeliveryDate")
	}

	diffDays := int(parsedActualDate.Sub(parsedAgreedDate).Hours() / 24)
	contractTerminated := false
	amountToBePaid := costofGoods
	tempPenalty := calculatePenalty(minTemperature, maxTemperature, penaltyFactor, tempSensorReading)
	humPenalty := calculatePenalty(minHumidity, maxHumidity, penaltyFactor, humSensorReading)
	totalPenalty := tempPenalty + humPenalty

	if diffDays > terminationDays {
		contractTerminated = true
		amountToBePaid = 0
	} else {
		amountToBePaid = max(costofGoods-totalPenalty, 0)
	}

	details := PerishableGoods{
		PerishableGoodsID:   PerishableGoodsId,
		AgreedDeliveryDate:  agreedDeliveryDate,
		ActualDeliveryDate:  actualDeliveryDate,
		MinTemperature:      minTemperature,
		MaxTemperature:      maxTemperature,
		MinHumidity:         minHumidity,
		MaxHumidity:         maxHumidity,
		PenaltyFactor:       penaltyFactor,
		TempSensorReading:   tempSensorReading,
		HumSensorReading:    humSensorReading,
		CostOfGoods:         costofGoods,
		AmountToBePaid:      amountToBePaid,
		TotalPenalty:        totalPenalty,
		ContractTerminated:  contractTerminated,
		TemperaturePenalty:  tempPenalty,
		HumidityPenalty:     humPenalty,
		Type:               "perishablegoods",
		DateTime:           time.Now().Format("2006-01-02 15:04:05"),
	}

	detailsJSON, err := json.Marshal(details)
	if err != nil {
		return err
	}

	return ctx.GetStub().PutState(PerishableGoodsId, detailsJSON)
}

func calculatePenalty(min, max, penaltyFactor int, readings string) int {
	values := strings.Split(readings, " ")
	count := 0
	for _, v := range values {
		num, err := strconv.Atoi(v)
		if err != nil {
			continue
		}
		if num < min || num > max {
			count++
		}
	}
	return count * penaltyFactor
}
