func (ac *AssetContract) QueryAllAssetsPublicProperties(ctx contractapi.TransactionContextInterface) (string, error) {
	startKey := ""
	endKey := ""
	allResults := make([]map[string]interface{}, 0)
	stateIterator, err := ctx.GetStub().GetStateByRange(startKey, endKey)
	if err != nil {
		return "", fmt.Errorf("failed to get state iterator: %v", err)
	}
	defer stateIterator.Close()

	for stateIterator.HasNext() {
		result, err := stateIterator.Next()
		if err != nil {
			return "", fmt.Errorf("failed to iterate over state: %v", err)
		}

		strValue := string(result.Value)
		var record map[string]interface{}
		err = json.Unmarshal([]byte(strValue), &record)
		if err != nil {
			record = map[string]interface{}{
				"Record": strValue,
			}
		}
		allResults = append(allResults, map[string]interface{}{
			"Key":   result.Key,
			"Record": map[string]interface{}{
				"Public_Mutable":   record["Public_Mutable"],
				"Public_Mandatory": record["Public_Mandatory"],
			},
			"OwnerOrg": record["OwnerOrg"],
			"Owner":    record["Owner"],
		})
	}

	allResultsJSON, err := json.Marshal(allResults)
	if err != nil {
		return "", fmt.Errorf("failed to marshal results: %v", err)
	}
	return string(allResultsJSON), nil
