	role, username, err := ac.validateRoleAndUsername(ctx)
	if err != nil {
		return "", err
	}

	if role == "AssetOwner" || role == "OrgAdmin" || role == "Admin" {
		assetAsBytes, err := ctx.GetStub().GetState(assetId)
		if err != nil {
			return "", fmt.Errorf("failed to read asset from state: %v", err)
		}
		if assetAsBytes == nil || len(assetAsBytes) == 0 {
			return "", fmt.Errorf("asset with id %s does not exist", assetId)
		}

		var assetSample map[string]interface{}
		err = json.Unmarshal(assetAsBytes, &assetSample)
		if err != nil {
			return "", fmt.Errorf("failed to unmarshal asset: %v", err)
		}

		if assetSample["Owner"] == username {
			assetSample["OwnerOrg"] = newOwnerOrg
			assetSample["Owner"] = newOwner

			updatedAssetJSON, err := json.Marshal(assetSample)
			if err != nil {
				return "", errors.New("failed to marshal updated asset")
			}

			err = ctx.GetStub().PutState(assetId, updatedAssetJSON)
			if err != nil {
				return "", fmt.Errorf("failed to update asset state: %v", err)
			}

