type LateInvoicePayment struct {
	LateInvoicePaymentId   string  `json:"LateInvoicePaymentId"`
	InvoiceAmountDue       float64 `json:"invoiceAmountDue"`
	InvoiceDueDate         string  `json:"invoiceDueDate"`
	InvoiceReceivedDate    string  `json:"invoiceReceivedDate"`
	LateInterestRate       float64 `json:"lateInterestRate"`
	LateInterestRateAmount float64 `json:"lateInterestRateAmount"`
	TotalAmount            float64 `json:"totalAmount"`
	Type                   string  `json:"type"`
	DateTime               string  `json:"dateTime"`
}

// LateInvoicePayment function implementation
func (s *SmartContract) LateInvoicePayment(ctx contractapi.TransactionContextInterface, requestOrderId string, LateInvoicePaymentId string, invoiceReceivedDate string, lateInterestRate float64) error {
	// Fetch order details from supplychaindata chaincode
	response := ctx.GetStub().InvokeChaincode("supplychaindata", [][]byte{[]byte("GetState"), []byte(requestOrderId)}, "mychannel")
	if response.Status != 200 {
		return errors.New("Order does not exist: " + requestOrderId)
	}

	// Parse order data
	var order map[string]interface{}
	err := json.Unmarshal(response.Payload, &order)
	if err != nil {
		return err
	}

	// Extract invoice due date and amount due from the order
	invoiceDueDate, ok := order["actualDeliveryDate"].(string)
	if !ok {
		return errors.New("Invalid or missing actualDeliveryDate in order")
	}
	invoiceAmountDue, ok := order["totalAmountPayable"].(float64)
	if !ok {
		return errors.New("Invalid or missing totalAmountPayable in order")
	}

	// Validate numeric inputs
	if lateInterestRate < 0 {
		return errors.New("Provide a valid input for lateInterestRate")
	}

	// Validate date format
	parsedDueDate, err := time.Parse("2006-01-02", invoiceDueDate)
	if err != nil {
		return errors.New("Provide correct date format yyyy-mm-dd for invoiceDueDate")
	}
	parsedReceivedDate, err := time.Parse("2006-01-02", invoiceReceivedDate)
	if err != nil {
		return errors.New("Provide correct date format yyyy-mm-dd for invoiceReceivedDate")
	}

	// Calculate late interest amount
	diffDays := int(math.Ceil(parsedReceivedDate.Sub(parsedDueDate).Hours() / 24))
	lateInterestRateAmount := float64(0)
	totalAmount := invoiceAmountDue

	if parsedReceivedDate.After(parsedDueDate) {
		lateInterestRateAmount = ((lateInterestRate / 100) * invoiceAmountDue * float64(diffDays))
		totalAmount += lateInterestRateAmount
	}

	// Update order with late payment details
	order["totalAmountPayable"] = totalAmount
	order["total_latePayment_Penalty"] = lateInterestRateAmount

	orderJSON, err := json.Marshal(order)
	if err != nil {
		return err
	}

	// Store updated order in supplychaindata chaincode
	ccUpdateArgs := [][]byte{[]byte("PutState"), []byte(requestOrderId), orderJSON}
	updateResponse := ctx.GetStub().InvokeChaincode("supplychaindata", ccUpdateArgs, "mychannel")
	if updateResponse.Status != 200 {
		return errors.New("Failed to update order in supplychaindata chaincode")
	}

	// Create struct for storing in ledger
	details := LateInvoicePayment{
		LateInvoicePaymentId:   LateInvoicePaymentId,
		InvoiceAmountDue:       invoiceAmountDue,
		InvoiceDueDate:         invoiceDueDate,
		InvoiceReceivedDate:    invoiceReceivedDate,
		LateInterestRate:       lateInterestRate,
		LateInterestRateAmount: lateInterestRateAmount,
		TotalAmount:            totalAmount,
		Type:                   "lateinvoicepayment",
		DateTime:               time.Now().Format("2006-01-02 15:04:05"),
	}

	// Convert to JSON
	detailsJSON, err := json.Marshal(details)
	if err != nil {
		return err
	}

	// Store invoice details in supplychaindata chaincode
	ccDetailsArgs := [][]byte{[]byte("PutState"), []byte(LateInvoicePaymentId), detailsJSON}
	detailsResponse := ctx.GetStub().InvokeChaincode("supplychaindata", ccDetailsArgs, "mychannel")
	if detailsResponse.Status != 200 {
		return errors.New("Failed to store late invoice payment details in supplychaindata chaincode")
	}

	fmt.Println("Late invoice payment details stored successfully:", details)
	return nil
}

