// ClaimSettlementToHospital processes a claim settlement to the hospital
func (s *SmartContract) ClaimSettlementToHospital(ctx contractapi.TransactionContextInterface, clientID, hospitalName, company, policyID string) (*ClaimSettlement, error) {

	// Generate composite key for claim
	compositeKey, err := ctx.GetStub().CreateCompositeKey("Claim", []string{clientID, company, policyID})
	if err != nil {
		return nil, fmt.Errorf("failed to create composite key: %v", err)
	}

	// Retrieve the client details
	clientData, err := ctx.GetStub().GetState(compositeKey)
	if err != nil || clientData == nil {
		return nil, fmt.Errorf("client ID %s does not exist", clientID)
	}

	var client ClaimSettlement
	err = json.Unmarshal(clientData, &client)
	if err != nil {
		return nil, fmt.Errorf("failed to parse client data: %v", err)
	}

	// Retrieve the claim details
	claimData, err := ctx.GetStub().GetState(compositeKey)
	if err != nil || claimData == nil {
		return nil, fmt.Errorf("claim ID for client %s does not exist", clientID)
	}

	var claim ClaimSettlement
	err = json.Unmarshal(claimData, &claim)
	if err != nil {
		return nil, fmt.Errorf("failed to parse claim data: %v", err)
	}

	// Validate that the client's policy matches the claim's policy
	if client.PolicyID != claim.PolicyID {
		return nil, fmt.Errorf("claimed policy ID does not match client policy ID")
	}

	// Generate composite key for hospital
	hospitalKey, err := ctx.GetStub().CreateCompositeKey(hospitalName, []string{claim.HospitalID, claim.PolicyID})
	if err != nil {
		return nil, fmt.Errorf("failed to create hospital composite key: %v", err)
	}

	// Retrieve hospital details
	hospitalData, err := ctx.GetStub().GetState(hospitalKey)
	if err != nil || hospitalData == nil {
		return nil, fmt.Errorf("hospital ID %s does not exist", claim.HospitalID)
	}

	var hospital ClaimSettlement
	err = json.Unmarshal(hospitalData, &hospital)
	if err != nil {
		return nil, fmt.Errorf("failed to parse hospital data: %v", err)
	}

	// Ensure the hospital is registered with the policy
	if hospital.PolicyID != claim.PolicyID {
		return nil, fmt.Errorf("hospital is not registered with the client's policy ID")
	}

	// Update the claim as settled
	claim.Status = "settled"
	claim.Type = "settlementtohospital"
	claim.DateTime = time.Now().Format("2006-01-02 15:04:05")

	// Convert claim object to JSON
	updatedClaimBytes, err := json.Marshal(claim)
	if err != nil {
		return nil, fmt.Errorf("failed to marshal updated claim: %v", err)
	}

	// Store the updated claim back in the ledger
	err = ctx.GetStub().PutState(compositeKey, updatedClaimBytes)
	if err != nil {
		return nil, fmt.Errorf("failed to update claim for client ID %s", clientID)
	}

	return &claim, nil
}
