func (s *DrugApprovalChaincode) CreateDrugApproval(ctx contractapi.TransactionContextInterface, drugID string, approvingAuthority string, maxDosage string, governmentApproval string) error {
	// Validate input parameters
	if drugID == "" || approvingAuthority == "" || maxDosage == "" || governmentApproval == "" {
		return errors.New("invalid number of arguments. Expecting 4")
	}

	// Ensure only the government agency can approve drugs
	if approvingAuthority != "CDSCO" {
		return errors.New("only government agency can approve drug")
	}

	// Verify Drug Test Report Exists
	reportID := fmt.Sprintf("TestReport-%s", drugID)
	reportAsBytes, err := ctx.GetStub().GetState(reportID)
	if err != nil || reportAsBytes == nil {
		return errors.New("cannot find drug report")
	}

	var testReport TestReport
	err = json.Unmarshal(reportAsBytes, &testReport)
	if err != nil {
		return err
	}

	// Verify Hash Integrity
	originalHash := testReport.Hash
	testReport.Hash = "" // Remove hash field before recalculating

	reportBytes, _ := json.Marshal(testReport)
	generatedHash := sha1.Sum(reportBytes)
	if originalHash != hex.EncodeToString(generatedHash[:]) {
		return errors.New("forged test report found")
	}

	// Retrieve Drug Data
	drugAsBytes, err := ctx.GetStub().GetState(drugID)
	if err != nil || drugAsBytes == nil {
		return fmt.Errorf("drug %s does not exist", drugID)
	}

	var drug Drug
	err = json.Unmarshal(drugAsBytes, &drug)
	if err != nil {
		return err
	}

	// Update Drug Information with Approval Details
	drug.GovernmentApprovalAuthority = approvingAuthority
	drug.MaxDosage = maxDosage
	drug.GovernmentApproval = governmentApproval
	drug.DocType = "Government_Approval"

	// Generate Government Approval Hash
	drugBytes, _ := json.Marshal(drug)
	hash := sha1.Sum(drugBytes)
	drug.GovernmentHash = hex.EncodeToString(hash[:])

	// Store Updated Drug Data
	updatedDrugBytes, _ := json.Marshal(drug)
	err = ctx.GetStub().PutState(drugID, updatedDrugBytes)
	if err != nil {
		return err
	}

	// Update and Store Test Report
	testReport.DocType = "Government_Approval"
	updatedReportBytes, _ := json.Marshal(testReport)
	err = ctx.GetStub().PutState(reportID, updatedReportBytes)
	if err != nil {
		return err
	}

	return nil
}
