// LateDeliveryandPenalty function implementation
func (s *SmartContract) LateDeliveryandPenalty(ctx contractapi.TransactionContextInterface, LateDeliveryandPenaltyId string, agreedDeliveryDate string, costOfGoods float64, lateFee float64, terminationDays int) error {
	// Validate date format
	parsedAgreedDate, err := time.Parse("2006-01-02", agreedDeliveryDate)
	if err != nil {
		return errors.New("Provide correct date format yyyy-mm-dd for agreedDeliveryDate")
	}

	// Get the current date (actual delivery date)
	actualDeliveryDate := time.Now()
	if parsedAgreedDate.After(actualDeliveryDate) {
		return errors.New("Cannot exercise late delivery before delivery date")
	}

	// Calculate delay in days
	diffDays := int(math.Ceil(actualDeliveryDate.Sub(parsedAgreedDate).Hours() / 24))
	fmt.Println("Delivered after", diffDays, "days")

	// Calculate penalty
	contractTerminated := false
	penaltyForSeller := float64(0)
	amountToBePaid := costOfGoods

	if diffDays > terminationDays {
		contractTerminated = true
	} else {
		penaltyForSeller = float64(diffDays) * lateFee
		amountToBePaid = math.Max(costOfGoods-penaltyForSeller, 0)
	}

	// Create struct for storing in ledger
	details := LateDeliveryandPenalty{
		LateDeliveryandPenaltyId: LateDeliveryandPenaltyId,
		CostOfGoods:              costOfGoods,
		TerminationDays:          terminationDays,
		AgreedDeliveryDate:       agreedDeliveryDate,
		ActualDeliveryDate:       actualDeliveryDate.Format("2006-01-02 15:04:05"),
		ContractTerminated:       contractTerminated,
		PenaltyForSeller:         penaltyForSeller,
		AmountToBePaid:           amountToBePaid,
		DiffDays:                 diffDays,
		LateFee:                  lateFee,
		Type:                     "latedeliveryandpenalty",
		DateTime:                 time.Now().Format("2006-01-02 15:04:05"),
	}

	// Convert to JSON
	detailsJSON, err := json.Marshal(details)
	if err != nil {
		return err
	}

	// Store in ledger
	err = ctx.GetStub().PutState(LateDeliveryandPenaltyId, detailsJSON)
	if err != nil {
		return err
	}

	fmt.Println("Late delivery penalty details stored successfully:", details)
	return nil
}// Non Design Pattern Ends

// Design Pattern Starts
type LateDeliveryandPenalty struct {
	LateDeliveryandPenaltyId string  `json:"LateDeliveryandPenaltyId"`
	CostOfGoods              float64 `json:"costofGoods"`
	TerminationDays          int     `json:"terminationDays"`
	AgreedDeliveryDate       string  `json:"agreedDeliveryDate"`
	ActualDeliveryDate       string  `json:"actualDeliveryDate"`
	ContractTerminated       bool    `json:"contractTerminated"`
	PenaltyForSeller         float64 `json:"penalty_for_seller"`
	AmountToBePaid           float64 `json:"amount_to_be_paid"`
	DiffDays                 int     `json:"diffDays"`
	LateFee                  float64 `json:"lateFee"`
	Type                     string  `json:"type"`
	DateTime                 string  `json:"dateTime"`
}

// LateDeliveryandPenalty function implementation
func (s *SmartContract) LateDeliveryandPenalty(ctx contractapi.TransactionContextInterface, LateDeliveryandPenaltyId string, agreedDeliveryDate string, costOfGoods float64, lateFee float64, terminationDays int) error {
	externalChaincode := "genericdata"
	channelName := "mychannel"

	// Validate agreed delivery date format
	parsedAgreedDate, err := time.Parse("2006-01-02", agreedDeliveryDate)
	if err != nil {
		return errors.New("provide correct date format yyyy-mm-dd for agreedDeliveryDate")
	}

	// Get actual delivery date
	actualDeliveryDate := time.Now()
	if parsedAgreedDate.After(actualDeliveryDate) {
		return errors.New("cannot exercise late delivery before the agreed delivery date")
	}

	// Calculate days delayed
	diffDays := int(math.Ceil(actualDeliveryDate.Sub(parsedAgreedDate).Hours() / 24))
	fmt.Println("Delivered after", diffDays, "days")

	// Calculate penalty
	contractTerminated := false
	penaltyForSeller := 0.0
	amountToBePaid := costOfGoods

	if diffDays > terminationDays {
		contractTerminated = true
	} else {
		penaltyForSeller = float64(diffDays) * lateFee
		amountToBePaid = math.Max(costOfGoods-penaltyForSeller, 0)
	}

	// Create LateDeliveryandPenalty struct
	details := LateDeliveryandPenalty{
		LateDeliveryandPenaltyId: LateDeliveryandPenaltyId,
		CostOfGoods:              costOfGoods,
		TerminationDays:          terminationDays,
		AgreedDeliveryDate:       agreedDeliveryDate,
		ActualDeliveryDate:       actualDeliveryDate.Format("2006-01-02 15:04:05"),
		ContractTerminated:       contractTerminated,
		PenaltyForSeller:         penaltyForSeller,
		AmountToBePaid:           amountToBePaid,
		DiffDays:                 diffDays,
		LateFee:                  lateFee,
		Type:                     "latedeliveryandpenalty",
		DateTime:                 time.Now().Format("2006-01-02 15:04:05"),
	}

	// Marshal to JSON
	detailsJSON, err := json.Marshal(details)
	if err != nil {
		return fmt.Errorf("failed to marshal penalty details: %v", err)
	}

	// Store in external chaincode using InvokeChaincode
	args := [][]byte{[]byte("PutState"), []byte(LateDeliveryandPenaltyId), detailsJSON}
	response := ctx.GetStub().InvokeChaincode(externalChaincode, args, channelName)

	if response.Status != 200 {
		return fmt.Errorf("failed to store penalty details via chaincode call: %s", response.Message)
	}

	fmt.Println("Late delivery penalty details stored successfully:", details)
	return nil
}

// Design Pattern Ends
